namespace BlazorApp.Services;

public class NotificationItem
{
    public int Id { get; set; }
    public string Message { get; set; } = string.Empty;
    public DateTime Timestamp { get; set; }
}

public class NotificationService
{
    private int _nextId = 1;
    private readonly List<NotificationItem> _notifications = new();
    private readonly Lock _lock = new();

    public NotificationService()
    {
        // Seed with initial fake data.
        _notifications.AddRange(new[]
        {
            new NotificationItem { Id = _nextId++, Message = "Welcome to the app!", Timestamp = DateTime.UtcNow.AddMinutes(-10) },
            new NotificationItem { Id = _nextId++, Message = "Your profile was updated.", Timestamp = DateTime.UtcNow.AddMinutes(-5) },
            new NotificationItem { Id = _nextId++, Message = "New feature: dark mode is available.", Timestamp = DateTime.UtcNow.AddMinutes(-1) },
        });

        // Background thread adds a new notification every ~8 seconds to simulate activity.
        _ = Task.Run(async () =>
        {
            var messages = new[]
            {
                "Server backup completed.",
                "A new user signed up.",
                "Deployment succeeded.",
                "Disk usage warning: 85%.",
                "Scheduled maintenance tonight at 11 PM.",
                "New comment on your post.",
                "Payment received.",
            };
            var rng = new Random();
            while (true)
            {
                await Task.Delay(TimeSpan.FromSeconds(8));
                lock (_lock)
                {
                    _notifications.Add(new NotificationItem
                    {
                        Id = _nextId++,
                        Message = messages[rng.Next(messages.Length)],
                        Timestamp = DateTime.UtcNow,
                    });
                }
            }
        });
    }

    public List<NotificationItem> GetNotifications()
    {
        lock (_lock)
        {
            return _notifications.OrderByDescending(n => n.Timestamp).ToList();
        }
    }

    public List<NotificationItem> GetNotificationsSince(int lastSeenId)
    {
        lock (_lock)
        {
            return _notifications
                .Where(n => n.Id > lastSeenId)
                .OrderByDescending(n => n.Timestamp)
                .ToList();
        }
    }
}

@page "/notifications"
@rendermode InteractiveServer
@implements IDisposable
@inject BlazorApp.Services.NotificationService NotificationService

<PageTitle>Notifications</PageTitle>

<h1>
    Notifications
    @if (items is not null)
    {
        <span class="badge bg-primary rounded-pill ms-2">@items.Count</span>
    }
</h1>

@if (items is null)
{
    <p><em>Loading...</em></p>
}
else if (items.Count == 0)
{
    <p>No notifications.</p>
}
else
{
    <ul class="list-group">
        @foreach (var n in items)
        {
            <li class="list-group-item d-flex justify-content-between align-items-start">
                <span>@n.Message</span>
                <small class="text-muted">@n.Timestamp.ToString("HH:mm:ss")</small>
            </li>
        }
    </ul>
}

@code {
    [PersistentState]
    public List<BlazorApp.Services.NotificationItem>? items { get; set; }

    private int _lastSeenId;
    private CancellationTokenSource? _cts;

    protected override void OnInitialized()
    {
        // Only fetch if state was NOT restored from prerender.
        items ??= NotificationService.GetNotifications();
        _lastSeenId = items.Count > 0 ? items.Max(n => n.Id) : 0;
    }

    protected override void OnAfterRender(bool firstRender)
    {
        if (firstRender)
        {
            // OnAfterRender is never called during prerender,
            // so the polling loop only starts once the page is truly interactive.
            _cts = new CancellationTokenSource();
            _ = PollForNotificationsAsync(_cts.Token);
        }
    }

    private async Task PollForNotificationsAsync(CancellationToken ct)
    {
        while (!ct.IsCancellationRequested)
        {
            await Task.Delay(TimeSpan.FromSeconds(5), ct).ConfigureAwait(false);

            var newer = NotificationService.GetNotificationsSince(_lastSeenId);
            if (newer.Count > 0)
            {
                await InvokeAsync(() =>
                {
                    // Prepend new items (they're already sorted desc).
                    items = newer.Concat(items ?? []).ToList();
                    _lastSeenId = items.Max(n => n.Id);
                    StateHasChanged();
                });
            }
        }
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
    }
}

